export const TASK_BAR_CSS = "/* ── TaskBar · 通知任务中心的通用展示栏 ──────────────────────────────────────\n   触发器本体就是 Button（描边档）：圆角 / 边框 / hover / 焦点环全在 button.css，\n   本文件只补它没有的：图标位的小绿点、计数文案、下拉里的行内排版。\n   下拉容器走 PanelSurface(menu)，这里只给宽度与滚动区，不改面板皮肤。 */\n\n.dshpc-taskbar{display:inline-flex;}\n\n/* 图标位：绿点钉在右上角，不参与布局。 */\n.dshpc-taskbar__iconwrap{position:relative;display:inline-flex;align-items:center;justify-content:center;}\n.dshpc-taskbar__dot{\n  position:absolute;top:-1px;right:-2px;width:6px;height:6px;border-radius:50%;\n  background:var(--dshpc-success);box-shadow:0 0 0 2px var(--dshpc-surface-base);\n}\n.dshpc-taskbar__count{color:var(--dshpc-fg-3);font-variant-numeric:tabular-nums;margin-left:2px;}\n\n/* 面板只补布局：宽度跟着视口收，列表自己滚。 */\n.dshpc-taskbar__panel{width:min(340px,calc(100vw - 24px));padding:var(--dshpc-space-1);}\n.dshpc-taskbar__list{\n  display:flex;flex-direction:column;gap:2px;\n  max-height:320px;overflow:auto;padding:2px;\n}\n.dshpc-taskbar__empty{\n  padding:var(--dshpc-space-4) var(--dshpc-space-3);text-align:center;\n  color:var(--dshpc-fg-3);font-size:var(--dshpc-font-sm);line-height:var(--dshpc-line-sm);\n}\n\n/* 一行：图标 + 两行文字；右侧按钮由 ListRow 的 actions 槽负责。 */\n.dshpc-taskbar__row{display:flex;align-items:center;gap:var(--dshpc-space-2);flex:1 1 auto;min-width:0;}\n.dshpc-taskbar__row-icon{\n  flex:none;display:inline-flex;align-items:center;justify-content:center;\n  width:22px;height:22px;border-radius:var(--dshpc-radius-sm);\n  background:var(--dshpc-surface-sunken);color:var(--dshpc-fg-2);\n}\n.dshpc-taskbar__row-main{display:flex;flex-direction:column;gap:1px;min-width:0;flex:1 1 auto;}\n.dshpc-taskbar__row-title{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}\n.dshpc-taskbar__row-meta{font-size:var(--dshpc-font-sm);line-height:var(--dshpc-line-sm);color:var(--dshpc-fg-3);}\n";
